public static class Billing
{
    public static DateOnly BillingDate(DateOnly start, int n)
    {
        if (n < 0) throw new ArgumentOutOfRangeException(nameof(n));
        var month = new DateOnly(start.Year, start.Month, 1).AddMonths(n);
        int day = Math.Min(start.Day, DateTime.DaysInMonth(month.Year, month.Month));
        return new DateOnly(month.Year, month.Month, day);
    }

    public static decimal Prorate(DateOnly from, DateOnly to, decimal monthlyPrice, DateOnly start)
    {
        if (to < from || from < start) throw new ArgumentException("bad range");
        int n = 0;
        while (BillingDate(start, n + 1) <= from) n++;
        var periodStart = BillingDate(start, n);
        var periodEnd = BillingDate(start, n + 1);
        if (to > periodEnd) throw new ArgumentException("range crosses a billing date");
        int days = to.DayNumber - from.DayNumber;
        int periodDays = periodEnd.DayNumber - periodStart.DayNumber;
        return Math.Round(monthlyPrice * days / periodDays, 2, MidpointRounding.AwayFromZero);
    }
}

unitTests:
var start = new DateOnly(2026, 1, 31);

Test("billing dates follow the start day", () =>
{
    CheckEq(Billing.BillingDate(start, 0), new DateOnly(2026, 1, 31));
    CheckEq(Billing.BillingDate(start, 1), new DateOnly(2026, 2, 28));
    CheckEq(Billing.BillingDate(start, 2), new DateOnly(2026, 3, 31));
    CheckEq(Billing.BillingDate(start, 3), new DateOnly(2026, 4, 30));
    CheckEq(Billing.BillingDate(new DateOnly(2027, 12, 31), 2), new DateOnly(2028, 2, 29));
});

Test("a whole period costs the monthly price", () =>
{
    CheckEq(Billing.Prorate(new DateOnly(2026, 2, 28), new DateOnly(2026, 3, 31), 31m, start), 31m);
});

Test("part of a period", () =>
{
    var s = new DateOnly(2026, 4, 1);
    CheckEq(Billing.Prorate(new DateOnly(2026, 4, 1), new DateOnly(2026, 4, 11), 30m, s), 10m);
    CheckEq(Billing.Prorate(new DateOnly(2026, 4, 5), new DateOnly(2026, 4, 6), 10m, s), 0.33m);
});

Test("bad ranges", () =>
{
    var s = new DateOnly(2026, 4, 1);
    CheckThrows<ArgumentException>(() => Billing.Prorate(new DateOnly(2026, 4, 10), new DateOnly(2026, 4, 5), 10m, s));
    CheckThrows<ArgumentException>(() => Billing.Prorate(new DateOnly(2026, 4, 25), new DateOnly(2026, 5, 3), 10m, s));
});

